}

query getMailboxThreads($mailBoxID: String!, $offset: BigInt!, $limit: BigInt!, $filter: String!) {
  mailbox(id: $mailBoxID) {
    id
    threads_count(threads_count_filter: "all") {
        inbox
        read
        unread
        sent
        archive
    }
    mailthreads(offset: $offset, limit: $limit, threads_filter: $filter) {
        count
        data {
            id
            subject
            labels
            read
            updated_time
            message_count
            mailbox {
                id
            }
            recipients {
                id
                name
                country
                gender
                personal_photo {
                    id
                    type
                    thumbnails {
                        url
                    }
                }
            }
            last_message {
                id
                body
                time
                mail_thread {
                    id
                }
                sender {
                    id
                    name
                    gender
                    country
                    personal_photo {
                        id
                        type
                        thumbnails {
                            url
                        }
                    }
                }
            }
        }
    }
  }
}

query getIndividualsIndexesForTree($treeID: String!, $sortType: String!, $offset: BigInt!, $limit: BigInt!) {
  tree(id: $treeID) {
    individuals(sort_by: $sortType, offset: $offset, limit: $limit) {
