      data {
        id
      }
    }
  }
}

query getSortedIndividuals($treeId: String!, $sortType: String, $offset: BigInt!, $limit: BigInt, $lang: String!) {
    tree(id: $treeId, lang: $lang) {
        site {
            id
            site_indexing_status
        }
        individuals(sort_by: $sortType, offset: $offset, limit: $limit, filter:"has_photo_tags") {
            count
            data {
                id
                tree {
                    id
                }
                name
                first_name
                last_name
                married_surname
                gender
                is_alive
                personal_photo {
                    ...photoFields
                }
                relationship {
                    relationship_type
                    relationship_description
                }
                birth_date {
                    ...dateFields
                }
                death_date {
                    ...dateFields
                }
                media(media_type: "photo") {
                    count
                }
            }
        }
    }
}

