query getTimelineEvents($individualID: String!, $lang: String!) {
  individual(id: $individualID, lang: $lang) {
    ...individualEventsAndFamilyFields
    ...individualFields
    close_family(hops: 2, lang: $lang) {
        data {
          relationship_type
          relationship_description
          individual {
            ...individualEventsAndFamilyFields
            ...individualFields
          }
        }
      }
    immediate_family(lang: $lang) {
      data {
        relationship_type
        relationship_description
        individual {
          ...individualEventsAndFamilyFields
          ...individualFields
        }
      }
    }
  }
}

