query getResearchCatalog($searchID: String!, $facetType: String!, $withCollections: Boolean!, $sortCollectionsBy: String!, $collectionsLimit: BigInt, $lang: String!) {
    search(id:$searchID, lang:$lang) {
        catalog {
            id
            summary {
                id
                total_record_count
                facets(facet_type: $facetType) {
                    facet_id
                    name
                    collection_count
                    record_count
                    description
                    thumbnail {
                        url
                        width
                        height
                    }
                }
            }
            collections(is_only_new_collections: true, sort_by: $sortCollectionsBy, limit: $collectionsLimit) @include(if: $withCollections) {
                count
                data {
                    id
                      name
                    category
                    record_count
                    short_description
                    is_new
                      has_images
                    is_featured
                    thumbnail {
                        url
                        width
                        height
                    }
                    category_chain {
                        id
                    }
                }
            }
        }
    }
}

