query getUserDeleteAccountDetails($userID: String!, $lang: String!) {
  user(id: $userID, lang: $lang) {
    name
    memberships(filter: "deleted_on_account_deletion") {
      data {
        site {
          ...getUserDeleteAccountDetailsSiteFields
        }
      }
    }
    subscriptions(include_subscriptions_contained_in_package: false, include_derived_subscriptions: false, subscription_status: "active") {
      count
      data {
        ...getUserDeleteAccountDetailsSubscriptionFields
      }
    }
    dna_kits(filter: "deleted_on_account_deletion") {
      data {
        ...getUserDeleteAccountDetailsDnaKitsFields
      }
    }
  }
}

fragment getUserDeleteAccountDetailsSiteFields on Site {
    id
    name
    media_count
    trees {
        data {
            name
            individual_count
        }
    }
}

fragment getUserDeleteAccountDetailsSubscriptionFields on Subscription {
    id
    site {
        id
        name
    }
    status
    remaining_duration
    free_trial_days_left
    is_mobile_subscription
    associated_kit {
        name
    }
    product {
        id
        name
    }
}

fragment getUserDeleteAccountDetailsDnaKitsFields on DnaKit {
    serial_number
    activation_status
    product_type
    name
    source
    member {
        id
    }
    submitter {
        id
    }
    associated_individual {
        id
        name
    }
    product_properties {
        data {
            results_status
        }
    }
}

